/* ── Page header ── */
header {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  padding: 0 32px;
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--color-text-primary);
  letter-spacing: -0.3px;
}

.logo span {
  color: var(--color-accent);
}

nav {
  display: flex;
  gap: 24px;
}

nav a {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  text-decoration: none;
  transition: color var(--transition);
}

nav a:hover,
nav a[aria-current="page"] {
  color: var(--color-text-primary);
}

/* ── Main layout ── */
main {
  flex: 1;
  padding: 40px 32px;
  max-width: 960px;
  width: 100%;
  margin: 0 auto;
}

.page-title {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.4px;
  margin-bottom: 4px;
}

.page-subtitle {
  font-size: 0.875rem;
  color: var(--color-text-secondary);
  margin-bottom: 32px;
}

/* ── Image card ── */
.image-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  max-width: 520px;
}

.image-preview {
  width: 100%;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  background: #e8eaf0;
  position: relative;
}

.image-preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.image-meta {
  padding: 20px 24px;
  border-bottom: 1px solid var(--color-border);
}

.image-name {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 4px;
}

.image-details {
  font-size: 0.8125rem;
  color: var(--color-text-secondary);
  display: flex;
  gap: 16px;
}

.image-actions {
  padding: 16px 24px;
  display: flex;
  gap: 12px;
  align-items: center;
}

/* ── Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.875rem;
  font-weight: 500;
  padding: 9px 18px;
  border-radius: var(--radius-sm);
  border: none;
  cursor: pointer;
  transition: background var(--transition), color var(--transition), box-shadow var(--transition);
